<?php
declare(strict_types=1);$active_module='hotel_control';require_once __DIR__.'/layout.php';if(empty($_SESSION['supplier_csrf']))$_SESSION['supplier_csrf']=bin2hex(random_bytes(32));$u=$supplier_user;$pdo=db();$message='';$error='';try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['supplier_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Güvenlik doğrulaması geçersiz.');$action=$_POST['action']??'';if($action==='checkin_link'){$booking=(int)$_POST['booking_id'];$q=$pdo->prepare('SELECT id FROM supplier_bookings WHERE id=? AND supplier_id=?');$q->execute([$booking,$u['supplier_id']]);if(!$q->fetch())throw new RuntimeException('Rezervasyon bulunamadı.');$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO booking_checkin_links(booking_id,token_hash,locale,expires_at) VALUES(?,?,?,?)')->execute([$booking,hash('sha256',$token),$_POST['locale']??'tr',date('c',strtotime('+72 hours'))]);$message='Online check-in bağlantısı: https://nexustraveltech.com/misafir/checkin?token='.$token;}if($action==='widget'){$property=(int)$_POST['property_id'];$enabled=isset($_POST['enabled']);$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO property_booking_widgets(property_id,is_enabled,public_token,confirmation_mode,updated_at) VALUES(?,?,?,?,now()) ON CONFLICT(property_id) DO UPDATE SET is_enabled=EXCLUDED.is_enabled,confirmation_mode=EXCLUDED.confirmation_mode,updated_at=now()')->execute([$property,$enabled,$token,$_POST['confirmation_mode']??'request']);$message='Doğrudan satış ayarı kaydedildi.';}if($action==='service_booking'){$pdo->prepare('INSERT INTO service_bookings(property_service_id,booking_id,guest_id,starts_at,ends_at,quantity,status,notes) VALUES(?,?,?,?,?,?,\'reserved\',?)')->execute([(int)$_POST['service_id'],(int)$_POST['booking_id']?:null,(int)$_POST['guest_id']?:null,$_POST['starts_at'],$_POST['ends_at']?:null,max(1,(int)$_POST['quantity']),trim((string)$_POST['notes'])?:null]);$message='Ek hizmet rezervasyonu oluşturuldu.';}if($action==='close_day'){$pdo->prepare('INSERT INTO hotel_daily_closures(property_id,business_date,closed_by,notes) VALUES(?,?,?,?)')->execute([(int)$_POST['property_id'],$_POST['business_date'],$u['id'],trim((string)$_POST['notes'])?:null]);$message='Gün sonu kapatıldı.';}}}catch(Throwable $e){$error=$e->getMessage();}$q=$pdo->prepare("SELECT p.id,p.name,w.is_enabled,w.public_token,w.confirmation_mode FROM properties p LEFT JOIN property_booking_widgets w ON w.property_id=p.id WHERE p.supplier_id=? AND p.property_type='hotel' ORDER BY p.name");$q->execute([$u['supplier_id']]);$hotels=$q->fetchAll();$q=$pdo->prepare("SELECT b.id,b.booking_reference,p.name property_name,g.id guest_id,g.first_name,g.last_name FROM supplier_bookings b JOIN properties p ON p.id=b.property_id LEFT JOIN booking_guests bg ON bg.booking_id=b.id AND bg.is_primary=true LEFT JOIN guest_profiles g ON g.id=bg.guest_id WHERE b.supplier_id=? AND p.property_type='hotel' ORDER BY b.id DESC LIMIT 100");$q->execute([$u['supplier_id']]);$bookings=$q->fetchAll();$q=$pdo->prepare('SELECT s.*,p.name property_name FROM property_services s JOIN properties p ON p.id=s.property_id WHERE p.supplier_id=? AND s.is_active=true ORDER BY p.name,s.name');$q->execute([$u['supplier_id']]);$services=$q->fetchAll();$q=$pdo->prepare("SELECT p.name,COUNT(DISTINCT b.id) booking_count,COALESCE(SUM(b.total_amount),0) sales,COUNT(DISTINCT CASE WHEN b.booking_status='in_house' THEN b.id END) in_house,COUNT(DISTINCT CASE WHEN b.booking_status='cancelled' THEN b.id END) cancellations FROM properties p LEFT JOIN supplier_bookings b ON b.property_id=p.id AND b.created_at>=current_date-interval '30 day' WHERE p.supplier_id=? AND p.property_type='hotel' GROUP BY p.id,p.name ORDER BY p.name");$q->execute([$u['supplier_id']]);$reports=$q->fetchAll();supply_start('Otel kontrol, misafir & raporlar',$active_module);?><section class="page-intro"><p>Online check-in, otelin kendi sitesinden satış, ek hizmet rezervasyonları, gün sonu ve son 30 gün operasyon özetini yönetin.</p></section><?php if($message):?><p class="save-success">✓ <?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="login-error"><?=htmlspecialchars($error)?></p><?php endif;?><section class="next-module"><h2>Online check-in bağlantısı</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="checkin_link"><div class="form-row"><label>Rezervasyon<select name="booking_id"><?php foreach($bookings as $b):?><option value="<?=$b['id']?>"><?=htmlspecialchars($b['booking_reference'].' · '.$b['property_name'])?></option><?php endforeach;?></select></label><label>Dil<select name="locale"><option value="tr">Türkçe</option><option value="en">English</option><option value="de">Deutsch</option><option value="ru">Русский</option></select></label></div><button>Güvenli check-in bağlantısı üret</button></form></section><section class="next-module"><h2>Otel web sitesi için doğrudan satış</h2><?php foreach($hotels as $h):?><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="widget"><input type="hidden" name="property_id" value="<?=$h['id']?>"><b><?=htmlspecialchars($h['name'])?></b><label><input type="checkbox" name="enabled" <?=$h['is_enabled']?'checked':''?>> Doğrudan satış talebi açık</label><select name="confirmation_mode"><option value="request">Taleple onay</option><option value="instant">Anlık onay</option></select><button>Kaydet</button><?php if($h['public_token']):?><p>Satış linki: <input readonly value="https://nexustraveltech.com/rezervasyon?property=<?=$h['id']?>&token=<?=htmlspecialchars($h['public_token'])?>"></p><?php endif;?></form><?php endforeach;?></section><section class="next-module"><h2>Ek hizmet rezervasyonu</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="service_booking"><div class="form-row"><label>Hizmet<select name="service_id"><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=htmlspecialchars($s['property_name'].' · '.$s['name'])?></option><?php endforeach;?></select></label><label>Rezervasyon<select name="booking_id"><option value="">Harici misafir</option><?php foreach($bookings as $b):?><option value="<?=$b['id']?>"><?=htmlspecialchars($b['booking_reference'])?></option><?php endforeach;?></select></label><label>Başlangıç<input type="datetime-local" name="starts_at" required></label><label>Bitiş<input type="datetime-local" name="ends_at"></label><label>Adet<input type="number" name="quantity" min="1" value="1"></label></div><textarea name="notes" placeholder="Not"></textarea><button>Hizmeti rezerve et</button></form></section><section class="next-module"><h2>Gün sonu</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="close_day"><div class="form-row"><select name="property_id"><?php foreach($hotels as $h):?><option value="<?=$h['id']?>"><?=htmlspecialchars($h['name'])?></option><?php endforeach;?></select><input type="date" name="business_date" value="<?=date('Y-m-d')?>"><input name="notes" placeholder="Kapanış notu"></div><button>Gün sonunu kapat</button></form></section><section class="next-module"><h2>Son 30 gün raporu</h2><?php foreach($reports as $r):?><p><b><?=htmlspecialchars($r['name'])?></b> · rezervasyon <?= (int)$r['booking_count']?> · satış <?=number_format((float)$r['sales'],2)?> · konaklayan <?= (int)$r['in_house']?> · iptal <?= (int)$r['cancellations']?></p><?php endforeach;?></section><?php supply_end();
